import React, { useState, useRef, useEffect } from 'react';

interface Point { x: number; y: number; label: number }
interface Split { axis: 'x' | 'y'; value: number; depth: number }

export const InteractiveTreeViz: React.FC = () => {
    const [splits, setSplits] = useState<Split[]>([]);
    const [points, setPoints] = useState<Point[]>([]);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Init random points
    useEffect(() => {
        const pts: Point[] = [];
        for (let i = 0; i < 30; i++) pts.push({ x: Math.random() * 300, y: Math.random() * 300, label: 0 }); // Class 0
        for (let i = 0; i < 30; i++) pts.push({ x: Math.random() * 300 + 100, y: Math.random() * 300 + 100, label: 1 }); // Class 1
        setPoints(pts);
    }, []);

    const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        // Simple heuristic: alternate split axis based on depth
        // In reality, trees search for best split. Here we let user "draw" splits by clicking.
        const axis = splits.length % 2 === 0 ? 'x' : 'y';
        const value = axis === 'x' ? x : y;

        setSplits([...splits, { axis, value, depth: splits.length }]);
    };

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const w = canvas.width;
        const h = canvas.height;
        ctx.clearRect(0, 0, w, h);

        // Draw Regions (Simplified visualization of recursive partition)
        // Correctly drawing regions for arbitrary user splits is complex (Kd-tree)
        // Visual hack: just draw the split lines

        ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
        ctx.lineWidth = 1;
        splits.forEach(split => {
            ctx.beginPath();
            if (split.axis === 'x') {
                ctx.moveTo(split.value, 0); ctx.lineTo(split.value, h);
            } else {
                ctx.moveTo(0, split.value); ctx.lineTo(w, split.value);
            }
            ctx.stroke();
        });

        // Draw Points
        points.forEach(p => {
            ctx.fillStyle = p.label === 0 ? '#3b82f6' : '#f59e0b';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 4, 0, 2 * Math.PI);
            ctx.fill();
        });

    }, [splits, points]);

    return (
        <div className="flex gap-4">
            <canvas
                ref={canvasRef}
                width={400}
                height={400}
                onClick={handleCanvasClick}
                className="bg-slate-900 rounded-lg border border-slate-700 cursor-crosshair"
            />
            <div className="flex-1 text-sm text-slate-400">
                <p className="mb-4">Click on the canvas to add a split decision.</p>
                <ul className="list-disc pl-4 space-y-2">
                    <li>Current Depth: {splits.length}</li>
                    <li>
                        A real Decision Tree algorithm (CART) automatically finds the split that maximizes "Information Gain" (reduces Entropy).
                    </li>
                </ul>
                <button
                    onClick={() => setSplits([])}
                    className="mt-4 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded"
                >
                    Reset Tree
                </button>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';

interface Point { x: number; y: number; cluster: number }
interface Centroid { x: number; y: number; color: string }

export const KMeansViz: React.FC = () => {
    const [points, setPoints] = useState<Point[]>([]);
    const [centroids, setCentroids] = useState<Centroid[]>([]);
    const [iteration, setIteration] = useState(0);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Init data
    useEffect(() => {
        const pts: Point[] = [];
        // Cluster 1
        for (let i = 0; i < 50; i++) pts.push({ x: 100 + Math.random() * 100, y: 100 + Math.random() * 100, cluster: -1 });
        // Cluster 2
        for (let i = 0; i < 50; i++) pts.push({ x: 300 + Math.random() * 100, y: 300 + Math.random() * 100, cluster: -1 });
        // Cluster 3
        for (let i = 0; i < 50; i++) pts.push({ x: 100 + Math.random() * 100, y: 300 + Math.random() * 100, cluster: -1 });

        setPoints(pts);

        // Random centroids
        setCentroids([
            { x: Math.random() * 500, y: Math.random() * 400, color: '#ef4444' },
            { x: Math.random() * 500, y: Math.random() * 400, color: '#3b82f6' },
            { x: Math.random() * 500, y: Math.random() * 400, color: '#10b981' },
        ]);
    }, []);

    const step = () => {
        // 1. Assign
        const newPoints = points.map(p => {
            let minDist = Infinity;
            let cluster = -1;
            centroids.forEach((c, idx) => {
                const d = Math.sqrt(Math.pow(p.x - c.x, 2) + Math.pow(p.y - c.y, 2));
                if (d < minDist) { minDist = d; cluster = idx; }
            });
            return { ...p, cluster };
        });
        setPoints(newPoints);

        // 2. Update
        const newCentroids = centroids.map((c, idx) => {
            const clusterPoints = newPoints.filter(p => p.cluster === idx);
            if (clusterPoints.length === 0) return c;
            const avgX = clusterPoints.reduce((s, p) => s + p.x, 0) / clusterPoints.length;
            const avgY = clusterPoints.reduce((s, p) => s + p.y, 0) / clusterPoints.length;
            return { ...c, x: avgX, y: avgY };
        });
        setCentroids(newCentroids);
        setIteration(i => i + 1);
    };

    const reset = () => {
        // Re-randomize centroids
        setCentroids([
            { x: Math.random() * 500, y: Math.random() * 400, color: '#ef4444' },
            { x: Math.random() * 500, y: Math.random() * 400, color: '#3b82f6' },
            { x: Math.random() * 500, y: Math.random() * 400, color: '#10b981' },
        ]);
        setIteration(0);
    };

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const w = canvas.width;
        const h = canvas.height;
        ctx.clearRect(0, 0, w, h);

        // Draw points
        points.forEach(p => {
            ctx.fillStyle = p.cluster === -1 ? '#475569' : centroids[p.cluster].color;
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3, 0, 2 * Math.PI);
            ctx.fill();
        });

        // Draw centroids
        centroids.forEach(c => {
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 2;
            ctx.fillStyle = c.color;
            ctx.beginPath();
            ctx.moveTo(c.x - 8, c.y - 8); ctx.lineTo(c.x + 8, c.y + 8);
            ctx.moveTo(c.x + 8, c.y - 8); ctx.lineTo(c.x - 8, c.y + 8);
            ctx.stroke();
            // Circle around centroid
            ctx.beginPath();
            ctx.arc(c.x, c.y, 10, 0, 2 * Math.PI);
            ctx.stroke();
        });

    }, [points, centroids]);

    return (
        <div className="flex gap-4 items-center">
            <canvas ref={canvasRef} width={500} height={400} className="bg-slate-900 rounded-lg border border-slate-700" />
            <div className="flex flex-col gap-4">
                <div className="text-xl font-bold text-white">Iteration: {iteration}</div>
                <button onClick={step} className="px-6 py-3 bg-blue-600 hover:bg-blue-500 rounded font-bold text-white">
                    Step Algorithm
                </button>
                <button onClick={reset} className="px-6 py-3 bg-slate-700 hover:bg-slate-600 rounded font-bold text-white">
                    Reset Centroids
                </button>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';

export const LikelihoodViz: React.FC = () => {
    // Fixed dataset
    const points = [-1.5, -0.5, 0.2, 0.8, 1.2];
    const [muEst, setMuEst] = useState(0);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const sigma = 1; // Fixed sigma for simplicity

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const width = canvas.width;
        const height = canvas.height;
        ctx.clearRect(0, 0, width, height);

        const xScale = 50;
        const yScale = 200;
        const xOffset = width / 2;
        const yBase = height - 50;

        // Draw Data Points
        points.forEach(x => {
            const px = xOffset + x * xScale;
            ctx.beginPath();
            ctx.arc(px, yBase, 5, 0, Math.PI * 2);
            ctx.fillStyle = '#ef4444'; // Red points
            ctx.fill();
        });

        // Draw Candidate Distribution
        ctx.beginPath();
        ctx.strokeStyle = '#10b981'; // Emerald
        ctx.lineWidth = 2;

        for (let px = 0; px < width; px++) {
            const xVal = (px - xOffset) / xScale;
            const pdf = Math.exp(-0.5 * Math.pow((xVal - muEst) / sigma, 2)); // Unnormalized height for visual
            const py = yBase - (pdf * 150);
            if (px === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.stroke();

        // Draw Likelihood Lines (Heights)
        let totalLogLike = 0;
        points.forEach(x => {
            const px = xOffset + x * xScale;
            const pdfVal = Math.exp(-0.5 * Math.pow((x - muEst) / sigma, 2));
            const py = yBase - (pdfVal * 150);

            ctx.beginPath();
            ctx.moveTo(px, yBase);
            ctx.lineTo(px, py);
            ctx.strokeStyle = '#ef4444';
            ctx.setLineDash([2, 2]);
            ctx.stroke();
            ctx.setLineDash([]);

            totalLogLike += Math.log(pdfVal); // Relative log likelihood
        });

        // Draw Likelihood Score
        ctx.fillStyle = '#10b981';
        ctx.font = '16px monospace';
        ctx.fillText(`Log-Likelihood: ${totalLogLike.toFixed(2)}`, 20, 30);

        // Optimal marker (True mean of sample is roughly 0.04)
        const trueMean = points.reduce((a, b) => a + b, 0) / points.length;
        if (Math.abs(muEst - trueMean) < 0.1) {
            ctx.fillText("MATCH! (MLE)", 20, 50);
        }

    }, [muEst]);

    return (
        <div className="space-y-4">
            <canvas
                ref={canvasRef}
                width={600}
                height={250}
                className="w-full bg-slate-900 rounded-lg border border-slate-700"
            />
            <div className="flex items-center gap-4">
                <span className="text-sm font-bold text-emerald-400">Estimated Mean ($\hat{'{'}\\mu{'}'}$): {muEst.toFixed(2)}</span>
                <input
                    type="range" min="-3" max="3" step="0.05"
                    value={muEst} onChange={(e) => setMuEst(parseFloat(e.target.value))}
                    className="flex-1 accent-emerald-500"
                />
            </div>
            <p className="text-xs text-slate-400">
                Move the green distribution. MLE finds the position where the red dashed lines (likelihood of each point) are maximized in total product (or sum of logs).
            </p>
        </div>
    );
};

