import React, { useState, useMemo } from 'react';

const sigmoid = (x: number) => 1 / (1 + Math.exp(-x));
const sigmoidDeriv = (x: number) => { const s = sigmoid(x); return s * (1 - s); };
const relu = (x: number) => Math.max(0, x);
const reluDeriv = (x: number) => x > 0 ? 1 : 0;
const tanh_ = (x: number) => Math.tanh(x);
const tanhDeriv = (x: number) => 1 - Math.tanh(x) ** 2;
const leakyRelu = (x: number) => x > 0 ? x : 0.01 * x;
const leakyReluDeriv = (x: number) => x > 0 ? 1 : 0.01;
const elu = (x: number) => x > 0 ? x : 1.0 * (Math.exp(x) - 1);
const eluDeriv = (x: number) => x > 0 ? 1 : 1.0 * Math.exp(x);
const swish = (x: number) => x * sigmoid(x);
const swishDeriv = (x: number) => { const s = sigmoid(x); return s + x * s * (1 - s); };

type ActivationType = 'sigmoid' | 'relu' | 'tanh' | 'leakyRelu' | 'elu' | 'swish';

const ACTIVATIONS: Record<ActivationType, { fn: (x: number) => number; deriv: (x: number) => number; color: string; label: string }> = {
    sigmoid: { fn: sigmoid, deriv: sigmoidDeriv, color: '#3b82f6', label: 'Sigmoid' },
    relu: { fn: relu, deriv: reluDeriv, color: '#22c55e', label: 'ReLU' },
    tanh: { fn: tanh_, deriv: tanhDeriv, color: '#f59e0b', label: 'Tanh' },
    leakyRelu: { fn: leakyRelu, deriv: leakyReluDeriv, color: '#8b5cf6', label: 'Leaky ReLU' },
    elu: { fn: elu, deriv: eluDeriv, color: '#ec4899', label: 'ELU' },
    swish: { fn: swish, deriv: swishDeriv, color: '#14b8a6', label: 'Swish' },
};

export const GradientFlowDemo: React.FC = () => {
    const [depth, setDepth] = useState(8);
    const [activation, setActivation] = useState<ActivationType>('sigmoid');

    // Simulate gradient magnitude through layers
    const gradientMagnitudes = useMemo(() => {
        const mags: number[] = [1.0]; // Start with gradient = 1 at output
        const actConfig = ACTIVATIONS[activation];

        for (let i = 1; i < depth; i++) {
            // Simulate: gradient *= weight * activation_derivative
            // For demonstration, use typical derivative values
            const typicalInput = 0.5 + Math.random() * 0.5; // Typical pre-activation value
            const derivValue = actConfig.deriv(typicalInput);
            const weight = 0.8 + Math.random() * 0.4; // Typical weight magnitude
            const prevMag = mags[i - 1] * derivValue * weight;
            mags.push(Math.max(prevMag, 1e-10)); // Clamp to avoid log(0)
        }

        return mags.reverse(); // Layer 0 (input) is first
    }, [depth, activation]);

    const maxMag = Math.max(...gradientMagnitudes);

    return (
        <div className="bg-slate-900/60 border border-white/10 rounded-xl p-6 my-6 backdrop-blur-sm">
            <div className="flex items-center justify-between mb-4">
                <div>
                    <h3 className="text-xl font-bold text-white">Gradient Flow Analysis</h3>
                    <p className="text-xs text-gray-500 mt-1">See how gradients vanish or explode across network depth</p>
                </div>
            </div>

            {/* Controls */}
            <div className="flex gap-6 mb-6">
                <label className="text-sm text-gray-400 flex items-center gap-3">
                    Network Depth:
                    <input type="range" min="3" max="20" value={depth}
                        onChange={e => setDepth(parseInt(e.target.value))}
                        className="w-32 accent-cyan-500"
                    />
                    <span className="text-cyan-400 font-mono font-bold w-6">{depth}</span>
                </label>
                <div className="flex gap-2">
                    {(Object.keys(ACTIVATIONS) as ActivationType[]).map(key => (
                        <button key={key} onClick={() => setActivation(key)}
                            className={`px-3 py-1 rounded-lg text-xs font-bold transition-all ${activation === key ? 'ring-1' : 'bg-white/5 text-gray-400 hover:bg-white/10'}`}
                            style={activation === key ? { backgroundColor: `${ACTIVATIONS[key].color}20`, color: ACTIVATIONS[key].color, borderColor: `${ACTIVATIONS[key].color}50` } : {}}
                        >{ACTIVATIONS[key].label}</button>
                    ))}
                </div>
            </div>

            {/* Gradient Heatmap */}
            <div className="bg-black/40 rounded-lg border border-white/5 p-4">
                <div className="flex items-end gap-1 h-40 justify-center">
                    {gradientMagnitudes.map((mag, i) => {
                        const normalizedHeight = maxMag > 0 ? (mag / maxMag) * 100 : 0;
                        const intensity = maxMag > 0 ? mag / maxMag : 0;
                        const isVanishing = mag < 0.01;

                        return (
                            <div key={i} className="flex flex-col items-center justify-end gap-1 h-full" style={{ width: `${Math.max(600 / depth, 20)}px` }}>
                                {/* Bar */}
                                <div className="w-full relative rounded-t-sm transition-all duration-300"
                                    style={{
                                        height: `${Math.max(normalizedHeight, 2)}%`,
                                        backgroundColor: isVanishing
                                            ? `rgba(239, 68, 68, ${0.3 + intensity * 0.7})`
                                            : `rgba(34, 211, 238, ${0.2 + intensity * 0.8})`,
                                        boxShadow: intensity > 0.5
                                            ? `0 0 ${intensity * 20}px rgba(34, 211, 238, ${intensity * 0.5})`
                                            : 'none',
                                    }}
                                />
                                {/* Label */}
                                <span className="text-[9px] text-gray-600 font-mono">L{i}</span>
                            </div>
                        );
                    })}
                </div>

                {/* Scale labels */}
                <div className="flex justify-between mt-3 text-[10px] text-gray-600 font-mono">
                    <span>Input Layer</span>
                    <span>Output Layer</span>
                </div>
            </div>

            {/* Diagnostic */}
            <div className={`mt-4 p-3 rounded-lg border text-sm ${gradientMagnitudes[0] < 0.001
                ? 'bg-red-500/10 border-red-500/20 text-red-300'
                : gradientMagnitudes[0] > 10
                    ? 'bg-orange-500/10 border-orange-500/20 text-orange-300'
                    : 'bg-green-500/10 border-green-500/20 text-green-300'
                }`}>
                {gradientMagnitudes[0] < 0.001 ? (
                    <><strong>⚠️ Vanishing Gradients!</strong> The gradient at the input layer is {gradientMagnitudes[0].toExponential(2)} — the early layers won't learn. This often happens with saturating activations.</>
                ) : gradientMagnitudes[0] > 10 ? (
                    <><strong>💥 Exploding Gradients!</strong> The gradient magnitude is {gradientMagnitudes[0].toFixed(1)} — training becomes unstable. Use gradient clipping or normalization.</>
                ) : (
                    <><strong>✅ Healthy Gradients.</strong> Gradient magnitude at input is {gradientMagnitudes[0].toFixed(4)} — learning will be stable across all layers.</>
                )}
            </div>
        </div>
    );
};

import React, { useState, useCallback } from 'react';

// Network architecture: 3 inputs → 4 hidden → 2 outputs
const LAYERS = [3, 4, 2];
const LAYER_LABELS = ['Input', 'Hidden', 'Output'];

// Sigmoid and its derivative
const sigmoid = (x: number) => 1 / (1 + Math.exp(-x));
const sigmoidDeriv = (s: number) => s * (1 - s);

// Random init helper
const randWeight = () => (Math.random() - 0.5) * 2;

interface NetworkState {
    weights: number[][][]; // weights[layer][to][from]
    biases: number[][];
    activations: number[][];
    zValues: number[][];
    deltas: number[][];
    weightGrads: number[][][];
}

function initNetwork(): NetworkState {
    const weights: number[][][] = [];
    const biases: number[][] = [[]];
    for (let l = 1; l < LAYERS.length; l++) {
        const layerW: number[][] = [];
        const layerB: number[] = [];
        for (let j = 0; j < LAYERS[l]; j++) {
            const neuronW: number[] = [];
            for (let k = 0; k < LAYERS[l - 1]; k++) {
                neuronW.push(randWeight());
            }
            layerW.push(neuronW);
            layerB.push(randWeight() * 0.5);
        }
        weights.push(layerW);
        biases.push(layerB);
    }
    return {
        weights, biases,
        activations: LAYERS.map(n => new Array(n).fill(0)),
        zValues: LAYERS.map(n => new Array(n).fill(0)),
        deltas: LAYERS.map(n => new Array(n).fill(0)),
        weightGrads: weights.map(lw => lw.map(nw => nw.map(() => 0))),
    };
}

function forwardPass(net: NetworkState, input: number[]): NetworkState {
    const activations = net.activations.map(a => [...a]);
    const zValues = net.zValues.map(a => [...a]);
    activations[0] = [...input];

    for (let l = 1; l < LAYERS.length; l++) {
        for (let j = 0; j < LAYERS[l]; j++) {
            let z = net.biases[l][j];
            for (let k = 0; k < LAYERS[l - 1]; k++) {
                z += net.weights[l - 1][j][k] * activations[l - 1][k];
            }
            zValues[l][j] = z;
            activations[l][j] = sigmoid(z);
        }
    }
    return { ...net, activations, zValues };
}

function backwardPass(net: NetworkState, target: number[]): NetworkState {
    const L = LAYERS.length - 1;
    const deltas = net.deltas.map(d => [...d]);
    const weightGrads = net.weightGrads.map(lw => lw.map(nw => [...nw]));

    // Output layer deltas
    for (let j = 0; j < LAYERS[L]; j++) {
        const error = net.activations[L][j] - target[j];
        deltas[L][j] = error * sigmoidDeriv(net.activations[L][j]);
    }

    // Hidden layer deltas
    for (let l = L - 1; l >= 1; l--) {
        for (let j = 0; j < LAYERS[l]; j++) {
            let sum = 0;
            for (let k = 0; k < LAYERS[l + 1]; k++) {
                sum += net.weights[l][k][j] * deltas[l + 1][k];
            }
            deltas[l][j] = sum * sigmoidDeriv(net.activations[l][j]);
        }
    }

    // Weight gradients
    for (let l = 0; l < net.weights.length; l++) {
        for (let j = 0; j < net.weights[l].length; j++) {
            for (let k = 0; k < net.weights[l][j].length; k++) {
                weightGrads[l][j][k] = deltas[l + 1][j] * net.activations[l][k];
            }
        }
    }

    return { ...net, deltas, weightGrads };
}

// Color helpers
function activationColor(val: number): string {
    const intensity = Math.round(val * 255);
    return `rgb(${intensity}, ${Math.round(intensity * 0.8)}, 255)`;
}

function gradientColor(val: number): string {
    const abs = Math.min(Math.abs(val) * 5, 1);
    if (val >= 0) return `rgba(34, 211, 238, ${abs})`; // cyan
    return `rgba(244, 114, 182, ${abs})`; // pink
}

// SVG Layout
const SVG_W = 700;
const SVG_H = 340;
const LAYER_X = [100, 350, 600];

function neuronY(layerIdx: number, neuronIdx: number): number {
    const count = LAYERS[layerIdx];
    const spacing = 70;
    const totalH = (count - 1) * spacing;
    return SVG_H / 2 - totalH / 2 + neuronIdx * spacing;
}

type Phase = 'idle' | 'forward' | 'backward';

export const NeuralNetworkBackpropViz: React.FC = () => {
    const [net, setNet] = useState<NetworkState>(initNetwork);
    const [phase, setPhase] = useState<Phase>('idle');
    const input = [0.8, 0.3, 0.6];
    const target = [0.9, 0.1];

    const runForward = useCallback(() => {
        setNet(prev => forwardPass(prev, input));
        setPhase('forward');
    }, []);

    const runBackward = useCallback(() => {
        setNet(prev => backwardPass(prev, target));
        setPhase('backward');
    }, []);

    const reset = useCallback(() => {
        setNet(initNetwork());
        setPhase('idle');
    }, []);

    return (
        <div className="bg-slate-900/60 border border-white/10 rounded-xl p-6 my-6 backdrop-blur-sm">
            <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-bold text-white">Live Neural Network</h3>
                <div className="flex gap-2">
                    <button onClick={runForward}
                        className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${phase === 'idle' ? 'bg-cyan-500/20 text-cyan-400 hover:bg-cyan-500/30 ring-1 ring-cyan-500/50' : 'bg-white/5 text-gray-500'}`}
                    >1. Forward Pass</button>
                    <button onClick={runBackward}
                        className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${phase === 'forward' ? 'bg-pink-500/20 text-pink-400 hover:bg-pink-500/30 ring-1 ring-pink-500/50' : 'bg-white/5 text-gray-500'}`}
                        disabled={phase !== 'forward'}
                    >2. Backward Pass</button>
                    <button onClick={reset}
                        className="px-4 py-1.5 rounded-lg text-sm bg-white/5 text-gray-400 hover:bg-white/10 transition-all"
                    >Reset</button>
                </div>
            </div>

            <div className="bg-black/40 rounded-lg border border-white/5 overflow-hidden">
                <svg viewBox={`0 0 ${SVG_W} ${SVG_H}`} className="w-full" style={{ maxHeight: '380px' }}>
                    {/* Connections */}
                    {net.weights.map((layerW, l) =>
                        layerW.map((neuronW, j) =>
                            neuronW.map((w, k) => {
                                const x1 = LAYER_X[l];
                                const y1 = neuronY(l, k);
                                const x2 = LAYER_X[l + 1];
                                const y2 = neuronY(l + 1, j);
                                const grad = net.weightGrads[l][j][k];
                                const showGrad = phase === 'backward';
                                const color = showGrad ? gradientColor(grad) : `rgba(255,255,255,${Math.min(Math.abs(w) * 0.3, 0.4)})`;
                                const width = showGrad ? Math.max(Math.abs(grad) * 8, 1) : Math.max(Math.abs(w) * 2, 0.5);

                                return (
                                    <line key={`w-${l}-${j}-${k}`}
                                        x1={x1} y1={y1} x2={x2} y2={y2}
                                        stroke={color}
                                        strokeWidth={width}
                                        strokeLinecap="round"
                                    />
                                );
                            })
                        )
                    )}

                    {/* Neurons */}
                    {LAYERS.map((count, l) =>
                        Array.from({ length: count }, (_, j) => {
                            const cx = LAYER_X[l];
                            const cy = neuronY(l, j);
                            const act = net.activations[l][j];
                            const delta = net.deltas[l][j];
                            const fill = phase === 'backward' && l > 0
                                ? gradientColor(delta)
                                : phase !== 'idle'
                                    ? activationColor(act)
                                    : '#334155';

                            return (
                                <g key={`n-${l}-${j}`}>
                                    <circle cx={cx} cy={cy} r={22} fill={fill}
                                        stroke={phase === 'backward' && l > 0 ? '#f472b6' : '#22d3ee'}
                                        strokeWidth={1.5} opacity={0.9}
                                    />
                                    <text x={cx} y={cy + 1} textAnchor="middle" dominantBaseline="middle"
                                        fill="white" fontSize="10" fontFamily="monospace"
                                    >
                                        {phase !== 'idle' ? act.toFixed(2) : '—'}
                                    </text>
                                    {phase === 'backward' && l > 0 && (
                                        <text x={cx} y={cy + 34} textAnchor="middle"
                                            fill="#f472b6" fontSize="9" fontFamily="monospace"
                                        >
                                            δ={delta.toFixed(3)}
                                        </text>
                                    )}
                                </g>
                            );
                        })
                    )}

                    {/* Layer Labels */}
                    {LAYER_LABELS.map((label, l) => (
                        <text key={`label-${l}`} x={LAYER_X[l]} y={20}
                            textAnchor="middle" fill="#64748b" fontSize="12" fontWeight="bold"
                        >{label}</text>
                    ))}
                </svg>
            </div>

            {/* Info */}
            <div className="mt-4 flex gap-4 text-xs">
                <div className="flex-1 p-3 bg-cyan-500/5 border border-cyan-500/20 rounded-lg">
                    <div className="text-cyan-400 font-bold mb-1">Forward Pass</div>
                    <div className="text-gray-500">Data flows left→right. Each neuron computes σ(Wx + b). Color = activation value.</div>
                </div>
                <div className="flex-1 p-3 bg-pink-500/5 border border-pink-500/20 rounded-lg">
                    <div className="text-pink-400 font-bold mb-1">Backward Pass</div>
                    <div className="text-gray-500">Errors flow right→left. δ values show each neuron's "blame". Line thickness = gradient magnitude.</div>
                </div>
            </div>
        </div>
    );
};

